import numpy as np
# grid across plausible admission profiles
names=INPUTS
# age (-4 means 20; 0 means 60; 3 means 90), l7 0..10
rows=[]
for age in [-4,-2,0,2,3]:
 for female in [0,1]:
  for wfns in [0,1]:
   for fisher in [0,1]:
    for ivh in [0,1]:
     for ich in [0,1]:
      for htn in [0,1]:
       for surgery in [0,1]:
        for urban in [0,1]:
         for farmer in [0,1]:
          for l7 in [0,2.5,5,7.5,10]:
           rows.append([age,female,wfns,fisher,ivh,ich,htn,surgery,urban,farmer,l7])
X=np.array(rows,float)
p=predict(X).reshape(-1)
def contrast(i, lo, hi, mask):
 xa=X[mask].copy(); xa[:,i]=lo
 xb=X[mask].copy(); xb[:,i]=hi
 return predict(xb).reshape(-1)-predict(xa).reshape(-1)
for key,i,lo,hi,mask in [
 ("urban",8,0,1,np.ones(len(X),bool)),
 ("farmer",9,0,1,np.ones(len(X),bool)),
 ("surgery",7,0,1,np.ones(len(X),bool))]:
 d=contrast(i,lo,hi,mask)
 print(key, "mean", d.mean(), "median",np.median(d),"q05/q95",np.quantile(d,[.05,.95]),"min/max",d.min(),d.max())
# contrasts paired: farmer effect in rural vs urban; and urban effect among farmer/nonfarmer
for subname, base, target in [
 ("rural farmer vs rural nonfarmer", {"urban":0,"farmer":0},{"urban":0,"farmer":1}),
 ("urban farmer vs urban nonfarmer", {"urban":1,"farmer":0},{"urban":1,"farmer":1}),
 ("rural nonfarmer vs urban nonfarmer", {"urban":1,"farmer":0},{"urban":0,"farmer":0}),
 ("rural farmer vs urban nonfarmer", {"urban":1,"farmer":0},{"urban":0,"farmer":1}),
 ("rural farmer vs urban farmer", {"urban":1,"farmer":1},{"urban":0,"farmer":1}),
]:
 m=np.ones(len(X),bool)
 for k,v in base.items():m &= X[:,names.index(k)]==v
 a=X[m].copy()
 b=a.copy()
 for k,v in target.items(): b[:,names.index(k)]=v
 d=predict(b).reshape(-1)-predict(a).reshape(-1)
 print(subname, "mean",d.mean(),"median",np.median(d),"q05/q95",np.quantile(d,[.05,.95]),"minmax",d.min(),d.max())
# effects farmer conditional surgery, urban
for urb in [0,1]:
 for surg in [0,1]:
  m=(X[:,8]==urb)&(X[:,7]==surg)
  d=contrast(9,0,1,m)
  print("farmer effect urban",urb,"surg",surg,"mean",d.mean(),"q",np.quantile(d,[.1,.5,.9]),"minmax",d.min(),d.max())
# rural effect conditioned farmer/surgery
for farm in [0,1]:
 for surg in [0,1]:
  m=(X[:,9]==farm)&(X[:,7]==surg)
  d=contrast(8,1,0,m) # changing city to rural
  print("rural effect farmer",farm,"surg",surg,"mean",d.mean(),"q",np.quantile(d,[.1,.5,.9]),"minmax",d.min(),d.max())

